// Stops the run while a setting is still a placeholder or makes no sense, then hands on the items of the
// trigger that started this run, each marked with where it came from. Nothing is sent or saved here.
const cfg = $('Your settings').first().json;
const problems = [];
const E164 = /^\+[1-9]\d{7,14}$/;
const text = (name) => String(cfg[name] ?? '').trim();

// Level 1 is required. Levels 2 and 3 may be empty: the ladder is then shorter.
const phones = [];
for (const name of ['oncall_phone_1', 'oncall_phone_2', 'oncall_phone_3']) {
  const value = text(name);
  if (!value) {
    if (name === 'oncall_phone_1') problems.push('oncall_phone_1 is empty: level 1 needs a number');
    continue;
  }
  if (!E164.test(value)) {
    problems.push(name + ' is not a real number yet (type it with + and the country code' + (name === 'oncall_phone_1' ? '' : ', or empty the field to use fewer levels') + ')');
  } else {
    phones.push(value);
  }
}
if (new Set(phones).size !== phones.length) problems.push('two on-call levels hold the same number');
if (!E164.test(text('owner_phone'))) problems.push('owner_phone is not a real number yet (the person who is told when nobody answers, with + and the country code)');

const positive = (name, whole) => {
  const value = Number(cfg[name]);
  if (!Number.isFinite(value) || value <= 0 || (whole && !Number.isInteger(value))) {
    problems.push(name + ' must be a ' + (whole ? 'whole ' : '') + 'number above 0');
  }
};
positive('ack_minutes', false);
positive('max_new_alerts_per_hour', true);
positive('rearm_hours', false);
positive('max_text_length', true);
const reopen = Number(cfg.reopen_minutes);
if (!Number.isFinite(reopen) || reopen < 0) problems.push('reopen_minutes must be a number of 0 or more');

const list = (name) => text(name).split(',').map((word) => word.trim().toLowerCase()).filter(Boolean);
if (list('ack_words').length === 0) problems.push('ack_words is empty: nobody could take an alert');
const order = list('severity_order');
if (!order.includes(text('min_severity').toLowerCase())) problems.push('min_severity must be one of severity_order (' + order.join(', ') + ')');
for (const name of ['field_alert_id', 'field_service', 'field_severity', 'field_status', 'field_message', 'field_runbook_url']) {
  if (!text(name)) problems.push(name + ' is empty: name the field of your alert that holds it');
}
for (const name of ['msg_page', 'msg_escalated', 'msg_final', 'msg_ack_confirm', 'msg_ack_note', 'msg_resolved']) {
  if (!text(name)) problems.push(name + ' is empty');
}
const button = text('runbook_button_text');
if (!button || button.length > 20) problems.push('runbook_button_text must be 1 to 20 characters');

if (problems.length > 0) {
  throw new Error('Not ready to page anybody: ' + problems.join('; ') + '. Fix Your settings, then the workflow runs.');
}

const source = $('Receive an alert').isExecuted ? 'alert' : $('Poll WhatsApp replies').isExecuted ? 'reply' : 'timer';
const items = source === 'alert' ? $('Receive an alert').all() : source === 'reply' ? $('Poll WhatsApp replies').all() : [{ json: {} }];
return items.map((item) => ({ json: { ...item.json, source } }));

// Reads the alert the monitoring tool sent, checks it, and decides: open a new incident, close one, or do nothing.
// The input is the rows of the table found for this alert id (and the alerts opened in the last hour).
// Nothing is sent or saved here. An alert is never refused for its looks: only a body that is not a JSON object
// or an id longer than 100 characters is rejected. A missing id gets one built from the service and the text.
const cfg = $('Your settings').first().json;
const hook = $('Receive an alert').first().json;
const body = hook && typeof hook.body === 'object' && hook.body !== null && !Array.isArray(hook.body) ? hook.body : null;
if (!body) throw new Error('Alert rejected: the request has no JSON object in its body.');

// Zero-width and direction-control characters are removed from every text that will be forwarded to a phone.
const clean = (value, max) =>
  String(value ?? '')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
    .trim()
    .slice(0, max);
const field = (setting) => body[String(cfg[setting]).trim()];
// A small, stable hash: the same text always gives the same number, so no randomness is needed.
const hash = (value) => {
  let h = 5381;
  for (const char of String(value)) h = (Math.imul(h, 33) + char.codePointAt(0)) >>> 0;
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d) >>> 0;
  return (h ^ (h >>> 12)) >>> 0;
};

const maxText = Math.floor(Number(cfg.max_text_length));
const service = clean(field('field_service'), Math.min(80, maxText)) || 'unknown service';
const severity = clean(field('field_severity'), 40).toLowerCase();
const message = clean(field('field_message'), maxText) || '(no message)';
// Only the word resolved closes an alert. Anything else, also a word this workflow does not know, is a firing alert.
const status = clean(field('field_status'), 20).toLowerCase() === 'resolved' ? 'resolved' : 'firing';
let alertId = clean(field('field_alert_id'), 101);
if (alertId.length > 100) {
  throw new Error('Alert rejected: the field "' + cfg.field_alert_id + '" holds an id longer than 100 characters.');
}
if (!alertId) alertId = 'auto-' + hash(service + '|' + message).toString(36); // no id: the same service and text count as the same alert
const runbook = clean(field('field_runbook_url'), 501);
const runbookUrl = runbook.length <= 500 && /^https?:\/\/\S+$/i.test(runbook) ? runbook : ''; // anything else is dropped, the page then has no button

const COLUMNS = ['alert_id', 'service', 'severity', 'message', 'status', 'level', 'notified_phone', 'message_id', 'notified_at', 'acknowledged_by', 'acknowledged_at', 'resolved_at', 'runbook_url', 'short_code', 'opened_at', 'pages', 'paged_phones', 'last_error'];
const pick = (row) => Object.fromEntries(COLUMNS.map((name) => [name, row[name] ?? (name === 'level' || name === 'pages' ? 0 : '')]));

const rows = $input.all().map((item) => item.json).filter((row) => row && row.alert_id);
const row = rows.find((candidate) => candidate.alert_id === alertId);
const now = Date.now();
const nowIso = new Date(now).toISOString();
const ageMs = (iso) => (Date.parse(iso) ? now - Date.parse(iso) : Infinity);

if (status === 'resolved') {
  // An open, a taken and a never-taken alert are all closed. The "Resolved" message goes to the people who were paged.
  if (row && ['open', 'acknowledged', 'unacknowledged'].includes(row.status)) {
    return [{ json: { action: 'resolve', row: { ...pick(row), status: 'resolved', resolved_at: nowIso } } }];
  }
  return []; // nothing to close
}

// Below the lowest severity that should page: ignore. An unknown or missing severity is NOT ignored.
const order = String(cfg.severity_order).split(',').map((word) => word.trim().toLowerCase()).filter(Boolean);
const rank = order.indexOf(severity);
if (rank !== -1 && rank < order.indexOf(String(cfg.min_severity).trim().toLowerCase())) return [];

// The same alert firing again. A resolved alert is a new incident after reopen_minutes (never less than one minute).
if (row) {
  const hours = Number(cfg.rearm_hours) * 3600000;
  if (row.status === 'open') return [];
  if (row.status === 'acknowledged' && ageMs(row.acknowledged_at) < hours) return [];
  if (row.status === 'unacknowledged' && ageMs(row.notified_at) < hours) return [];
  if (row.status === 'resolved' && ageMs(row.resolved_at) < Math.max(1, Number(cfg.reopen_minutes)) * 60000) return [];
}

// A new incident. Too many new alerts in one hour: nobody is paged, the run fails so that it is seen.
// The highest severity is never held back: a flood of noise must not hide the alert that matters.
const recent = rows.filter((candidate) => candidate.alert_id !== alertId && ageMs(candidate.opened_at) < 3600000).length;
if (rank !== order.length - 1 && recent >= Number(cfg.max_new_alerts_per_hour)) {
  throw new Error('Alert ' + alertId + ' (' + service + ') was NOT paged: ' + recent + ' other alerts were opened in the last hour and the limit is ' + cfg.max_new_alerts_per_hour + ' (max_new_alerts_per_hour). Look at your monitoring tool.');
}

// A short code that no open alert uses, without the characters people confuse (0 O 1 I L). It comes from the id and
// the minute, never from chance, so two identical requests at the same moment write the same text and the same key.
const ALPHABET = '23456ABCDEFGHJKMNPQRSTUVWXYZ789';
const codeFor = (seed) => {
  let n = hash(seed) % (ALPHABET.length ** 4);
  return Array.from({ length: 4 }, () => {
    const char = ALPHABET[n % ALPHABET.length];
    n = Math.floor(n / ALPHABET.length);
    return char;
  }).join('');
};
const taken = new Set(rows.filter((candidate) => candidate.status === 'open').map((candidate) => String(candidate.short_code)));
const minute = Math.floor(now / 60000);
let code = '';
for (let salt = 0; !code || taken.has(code); salt++) code = codeFor(alertId + '|' + minute + '|' + salt);

return [{
  json: {
    action: 'open',
    row: {
      alert_id: alertId, service, severity, message, status: 'open', level: 0, notified_phone: '', message_id: '',
      notified_at: '', acknowledged_by: '', acknowledged_at: '', resolved_at: '', runbook_url: runbookUrl,
      short_code: code, opened_at: nowIso, pages: 0, paged_phones: '', last_error: '',
    },
  },
}];

// Looks at the OPEN alerts. After a poll it matches the replies of the people who were paged to the alert they
// take. On the minute timer it finds the alerts whose current level did not answer in time (or whose page was
// refused) and so need the next level. Nothing is sent or saved here.
const cfg = $('Your settings').first().json;
const source = $('Check the settings').first().json.source;
const COLUMNS = ['alert_id', 'service', 'severity', 'message', 'status', 'level', 'notified_phone', 'message_id', 'notified_at', 'acknowledged_by', 'acknowledged_at', 'resolved_at', 'runbook_url', 'short_code', 'opened_at', 'pages', 'paged_phones', 'last_error'];
const pick = (row) => Object.fromEntries(COLUMNS.map((name) => [name, row[name] ?? (name === 'level' || name === 'pages' ? 0 : '')]));
const rows = $input.all().map((item) => item.json).filter((row) => row && row.alert_id && row.status === 'open');
const now = Date.now();
const nowIso = new Date(now).toISOString();
const digits = (value) => String(value ?? '').replace(/\D/g, '');
const pagedOf = (row) => String(row.paged_phones || '').split(',').map((phone) => phone.trim()).filter(Boolean);

if (source === 'timer') {
  // One minute of grace after ack_minutes: a reply written just before the deadline is read by the poll one tick
  // before the timer can escalate. Escalation therefore happens ack_minutes + 1 to + 2 minutes after the page.
  const ackMs = Number(cfg.ack_minutes) * 60000 + 60000;
  return rows
    .filter((row) => {
      const since = (iso) => (Date.parse(iso) ? now - Date.parse(iso) : Infinity); // a missing time counts as long ago
      if (!Number(row.level)) return since(row.opened_at) >= 120000; // opened, but no page went out (the run that opened it stopped)
      if (!row.message_id) return true; // the last page was refused: do not wait for an answer that cannot come
      return since(row.notified_at) >= ackMs; // nobody answered in time
    })
    .map((row) => ({ json: { action: 'page', row: pick(row) } }));
}

// Replies. A reply is: an acknowledgement word, optionally followed by the short code of the alert.
const normalize = (value) =>
  String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
const words = String(cfg.ack_words).split(',').map(normalize).filter(Boolean).sort((a, b) => b.length - a.length);
const listed = [cfg.oncall_phone_1, cfg.oncall_phone_2, cfg.oncall_phone_3].map(digits).filter(Boolean);
const events = $('Poll WhatsApp replies').all().map((item) => item.json);
const claimed = new Set();
const plain = new Set(); // phones that already took the newest alert with a message without a code, in this poll
const out = [];
for (const event of events) {
  const data = event.data || {};
  if (event.type !== 'message.received' && event.type !== 'message.replied') continue;
  if (data.direction !== 'inbound' || (data.to && data.to.group_id)) continue; // only private chats, only what people wrote
  if (data.content_type !== 'text') continue; // a picture with the caption OK is not an answer
  const from = digits(data.from && data.from.number);
  if (!from || !listed.includes(from)) continue; // somebody who is not on the list
  const phone = '+' + from;
  // The open alerts this person was paged for, the newest first.
  const mine = rows
    .filter((row) => !claimed.has(row.alert_id) && pagedOf(row).includes(phone))
    .sort((a, b) => Date.parse(b.opened_at) - Date.parse(a.opened_at));
  if (mine.length === 0) continue;
  const text = normalize(data.preview);
  const word = words.find((candidate) => text === candidate || text.startsWith(candidate + ' '));
  if (!word) continue; // anything else is ignored
  const rest = text.slice(word.length).trim();
  let target = mine[0]; // no code: the newest open alert of this person, once per poll (a second plain OK does not take another alert)
  if (rest === '') {
    if (plain.has(phone)) continue;
    plain.add(phone);
  } else {
    target = rest.includes(' ') ? undefined : mine.find((row) => normalize(row.short_code) === rest);
    if (!target) continue; // some other sentence, or a code that is not an open alert of this person
  }
  claimed.add(target.alert_id);
  out.push({
    json: {
      action: 'ack',
      responder: phone,
      responder_name: String((data.from && data.from.name) || '').trim().slice(0, 60),
      row: { ...pick(target), status: 'acknowledged', acknowledged_by: phone, acknowledged_at: nowIso },
    },
  });
}
return out;

// The one place that decides WHO gets WHICH message. It writes every text from the wording in Your settings.
// Nothing is sent or saved here: the items it returns are sent one by one by the send nodes that follow.
const cfg = $('Your settings').first().json;
const source = $('Check the settings').first().json.source;
const incoming = source === 'alert' ? $('Decide what to do with the alert').all() : $input.all();
const nowIso = new Date().toISOString();
const digits = (value) => String(value ?? '').replace(/\D/g, '');
const split = (value) => String(value || '').split(',').map((phone) => phone.trim()).filter(Boolean);
const phones = [cfg.oncall_phone_1, cfg.oncall_phone_2, cfg.oncall_phone_3].map((phone) => String(phone ?? '').trim()).filter(Boolean);
const owner = String(cfg.owner_phone).trim();
// {placeholders} are filled in; a typed backslash and n become a line break.
const fill = (template, values) =>
  String(template)
    .replace(/\\n/g, '\n')
    .replace(/\{(\w+)\}/g, (whole, name) => (name in values ? String(values[name]) : whole));
const safe = (value) => String(value).replace(/[^A-Za-z0-9._-]/g, '_');
// The same small hash as in the node that opens the alert. It keeps two ids that differ only in punctuation apart.
const hash = (value) => {
  let h = 5381;
  for (const char of String(value)) h = (Math.imul(h, 33) + char.codePointAt(0)) >>> 0;
  h = Math.imul(h ^ (h >>> 15), 0x2c1b3c6d) >>> 0;
  return (h ^ (h >>> 12)) >>> 0;
};
// The runbook link goes at the end of the page text as well as on the button: the whole body stays within 1000 characters.
const withLink = (text, url) => (url ? text.slice(0, 1000 - url.length - 1) + '\n' + url : text.slice(0, 1000));

const out = [];
for (const { json: item } of incoming) {
  const row = item.row;
  // One key per alert incident and message: sending it again returns the first message instead of a second one.
  const base = 'oncall-' + safe(row.alert_id).slice(0, 60) + '-' + hash(row.alert_id).toString(36) + '-' + Math.floor(Date.parse(row.opened_at) / 60000);
  const values = {
    service: row.service, severity: row.severity || 'n/a', message: row.message, code: row.short_code,
    alert_id: row.alert_id, minutes: cfg.ack_minutes,
  };
  const message = (kind, to, text, key, extra) => out.push({
    json: { alert_id: row.alert_id, kind, level: 0, to, text, runbook_url: '', button_text: cfg.runbook_button_text, key, row_after: row, paged_before: '', ...extra },
  });

  if (item.action === 'open' || item.action === 'page') {
    const level = Number(row.level) || 0;
    const paged = split(row.paged_phones);
    if (level < phones.length) {
      const to = phones[level];
      // The page that follows a level that was never reached is a first page for this person, not an escalation.
      const escalated = level > 0 && Boolean(row.message_id);
      const text = withLink(fill(escalated ? cfg.msg_escalated : cfg.msg_page, { ...values, level: level + 1, previous_level: level }), row.runbook_url);
      // After a refused page the button goes: whatever made it fail cannot keep this person from being paged. The link stays in the text.
      const refused = level > 0 && !row.message_id;
      message('page', to, text, base + '-L' + (level + 1), {
        level: level + 1,
        runbook_url: refused ? '' : row.runbook_url || '',
        paged_before: paged.join(','),
        row_after: { ...row, level: level + 1, notified_phone: to, notified_at: nowIso, pages: level + 1, paged_phones: [...paged, to].join(','), message_id: '', last_error: '' },
      });
    } else {
      // No level is left: ONE final message to everybody on the list and to the owner. Then it stops.
      const closed = { ...row, status: 'unacknowledged', notified_at: nowIso };
      for (const to of [...new Set([...phones, owner])]) {
        message('final', to, fill(cfg.msg_final, values), base + '-final-' + digits(to), { row_after: closed });
      }
    }
  } else if (item.action === 'ack') {
    message('ack_confirm', item.responder, fill(cfg.msg_ack_confirm, values), base + '-ack-' + digits(item.responder), {});
    const name = item.responder_name || item.responder;
    for (const to of split(row.paged_phones).filter((phone) => digits(phone) !== digits(item.responder))) {
      message('ack_note', to, fill(cfg.msg_ack_note, { ...values, name }), base + '-acknote-' + digits(to), {});
    }
  } else if (item.action === 'resolve') {
    for (const to of split(row.paged_phones)) {
      message('resolved', to, fill(cfg.msg_resolved, values), base + '-resolved-' + digits(to), {});
    }
  }
}
return out;

// Runs once, after every message of this run was sent or refused. Each answer of Turbo Notify is matched with the
// message that was planned for it. Then ONE small record per alert is written for the table, and it holds ONLY the
// columns this run owns: a page writes the level, the phone, the time and the message id; an acknowledgement writes
// who took the alert; the final message closes it; a "resolved" writes nothing but the failure. Because a save never
// repeats the columns it does not own, a run that was slow cannot undo an acknowledgement or a resolution that
// another run wrote in the meantime. A refused page is recorded, so the timer pages the next level without waiting
// for an answer that cannot come. A refused send arrives here as an error: it never stopped the other messages.
const reasonOf = (error) => String(typeof error === 'string' ? error : (error && error.message) || JSON.stringify(error)).slice(0, 200);

const results = $input.all().map((answer, index) => {
  const planned = $('Write the messages').itemMatching(index).json;
  const failed = Boolean(answer.json.error) || !answer.json.id;
  return {
    planned,
    ok: !failed,
    message_id: failed ? '' : answer.json.id,
    error: failed ? reasonOf(answer.json.error || 'Turbo Notify did not return a message id') : '',
  };
});

const byAlert = new Map();
for (const result of results) {
  if (!byAlert.has(result.planned.alert_id)) byAlert.set(result.planned.alert_id, []);
  byAlert.get(result.planned.alert_id).push(result);
}
const out = [];
for (const [alertId, own] of byAlert) {
  const kinds = new Set(own.map((result) => result.planned.kind));
  const failures = own.filter((result) => !result.ok).map((result) => result.planned.kind + ' to ' + result.planned.to + ': ' + result.error);
  const saved = { alert_id: alertId };
  const page = own.find((result) => result.planned.kind === 'page');
  if (page) {
    const after = page.planned.row_after;
    Object.assign(saved, {
      level: after.level,
      notified_phone: after.notified_phone,
      notified_at: after.notified_at,
      pages: after.pages,
      // A refused page does not count as a person who received it: only those reached can take the alert.
      paged_phones: page.ok ? after.paged_phones : page.planned.paged_before,
      message_id: page.ok ? page.message_id : '',
    });
  }
  if (kinds.has('final')) {
    const after = own.find((result) => result.planned.kind === 'final').planned.row_after;
    Object.assign(saved, { status: 'unacknowledged', notified_at: after.notified_at });
  }
  if (kinds.has('ack_confirm') || kinds.has('ack_note')) {
    const after = own.find((result) => result.planned.kind === 'ack_confirm' || result.planned.kind === 'ack_note').planned.row_after;
    Object.assign(saved, { status: 'acknowledged', acknowledged_by: after.acknowledged_by, acknowledged_at: after.acknowledged_at });
  }
  saved.last_error = failures.join(' | ');
  out.push({ json: saved });
}
return out;

// The last node of the run. A refused message is never silent: the row already holds it, and this node makes the
// run fail so that your Error workflow (or the Executions list) shows it, naming the alert and the person.
// Every refused message fails the run, also a page to a level that is followed by another level.
const cfg = $('Your settings').first().json;
const phoneCount = [cfg.oncall_phone_1, cfg.oncall_phone_2, cfg.oncall_phone_3].filter((phone) => String(phone ?? '').trim()).length;
const serviceOf = new Map($('Write the messages').all().map((item) => [item.json.alert_id, item.json.row_after.service]));
const lines = [];
for (const row of $('Update the alert rows').all().map((item) => item.json)) {
  if (!row.last_error) continue;
  // last_error holds one "kind to phone: reason" per refused message, separated by " | ".
  const failures = String(row.last_error).split(' | ');
  const label = 'Alert ' + row.alert_id + ' (' + (serviceOf.get(row.alert_id) || 'unknown service') + ')';
  const nobody = failures.some((failure) => failure.startsWith('page to ')) && row.paged_phones === '' && Number(row.level) >= phoneCount;
  if (nobody) {
    lines.push(label + ': NOBODY could be paged, every level failed. ' + row.last_error);
  } else {
    lines.push(label + ': ' + failures.map((failure) => failure.replace(/^(\w+) to (\S+): /, '$1 to $2 failed: ')).join(' | '));
  }
}
if (lines.length > 0) throw new Error(lines.join(' || '));
return $input.all();
